package markdown

import (
	"fmt"
	"strings"
)

// Render translates markdown to HTML.
//
// Refactoring notes:
//
// The original implementation scanned the input character by character,
// threading several pieces of state (header level, list depth, whether a
// list item was open, whether a header had ended) through one big loop,
// and pre-substituted emphasis markers across the whole document.
//
// The rewrite parses the input line by line instead. Each line is
// classified as one of three things and rendered by its own small helper:
//
//   - a header: starts with 1-6 '#' characters (7 or more is a paragraph)
//   - a list item: starts with "* "; consecutive items share one <ul>
//   - a paragraph: anything else
//
// Emphasis ("__bold__" and "_italic_") is translated per line with the
// same first-occurrence replacement the original used.
func Render(markdown string) string {
	var html strings.Builder
	inList := false

	for _, line := range strings.Split(markdown, "\n") {
		if isListItem(line) {
			if !inList {
				html.WriteString("<ul>")
				inList = true
			}
			html.WriteString(renderListItem(line))
			continue
		}

		if inList {
			html.WriteString("</ul>")
			inList = false
		}

		if level, ok := headerLevel(line); ok {
			html.WriteString(renderHeader(level, line))
		} else {
			html.WriteString(renderParagraph(line))
		}
	}

	if inList {
		html.WriteString("</ul>")
	}

	return html.String()
}

// isListItem reports whether line is a list item, i.e. starts with "* ".
func isListItem(line string) bool {
	return strings.HasPrefix(line, "* ")
}

// headerLevel reports the level of a header line. A header starts with
// 1-6 '#' characters; lines with any other number of leading '#' are
// not headers (ok is false) and are rendered as paragraphs.
func headerLevel(line string) (level int, ok bool) {
	for level < len(line) && line[level] == '#' {
		level++
	}
	if level == 0 || level > 6 {
		return 0, false
	}
	return level, true
}

// renderHeader renders a header line of the given level. The rest of the
// line is kept as-is (markdown symbols inside the text are not
// interpreted as structure), except for emphasis.
func renderHeader(level int, line string) string {
	text := strings.TrimPrefix(line, strings.Repeat("#", level))
	text = strings.TrimPrefix(text, " ")
	return fmt.Sprintf("<h%d>%s</h%d>", level, renderEmphasis(text), level)
}

// renderListItem renders a single list item without the surrounding
// <ul>, which Render adds around runs of consecutive items.
func renderListItem(line string) string {
	return "<li>" + renderEmphasis(strings.TrimPrefix(line, "* ")) + "</li>"
}

// renderParagraph renders a plain paragraph line.
func renderParagraph(line string) string {
	return "<p>" + renderEmphasis(line) + "</p>"
}

// renderEmphasis translates the first "__...__" pair to <strong> and the
// first "_..._" pair to <em>, as the original implementation did.
func renderEmphasis(line string) string {
	line = strings.Replace(line, "__", "<strong>", 1)
	line = strings.Replace(line, "__", "</strong>", 1)
	line = strings.Replace(line, "_", "<em>", 1)
	line = strings.Replace(line, "_", "</em>", 1)
	return line
}

